-- What is the total revenue generated by each day?
SELECT 
    Date,SUM(`Total Amount`) Daily_revenue 
FROM
    retail_sales_dataset
GROUP BY Date
order by Date asc;

-- Total Revenue generated by each column?

SELECT 
    YEAR(Date),
    MONTHNAME(Date),
    SUM(`Total Amount`) Monthly_Revenue
FROM
    retail_sales_dataset
GROUP BY YEAR(Date) , MONTHNAME(Date);

-- Month Generated the highest revenue

SELECT 
    YEAR(Date),
    MONTHNAME(Date),
    SUM(`Total Amount`) Monthly_Revenue
FROM
    retail_sales_dataset
GROUP BY YEAR(Date) , MONTHNAME(Date)
ORDER BY SUM(`Total Amount`) DESC
LIMIT 1;

-- Month Generated the lowest revenue

SELECT 
    YEAR(Date),
    MONTHNAME(Date),
    SUM(`Total Amount`) Monthly_Revenue
FROM
    retail_sales_dataset
GROUP BY YEAR(Date) , MONTHNAME(Date)
ORDER BY SUM(`Total Amount`) ASC
LIMIT 1;


-- Average Daily Revenue

with Daily_Rev as (select sum(`Total Amount`) Daily_Revenue
from retail_sales_dataset
group by date)
select AVG(Daily_Revenue) AVerage_Daily_Revenue from Daily_Rev;

-- Which day of the month Generates the highest revenue?
SELECT 
    DATE_FORMAT(Date, '%b-%d'),
    SUM(`Total Amount`) Daily_Revenue
FROM
    retail_sales_dataset
GROUP BY DATE_FORMAT(Date, '%b-%d')
ORDER BY SUM(`Total Amount`) DESC
LIMIT 1;


-- Which Year generate the highest total revenue

SELECT 
    DATE_FORMAT(Date, '%Y'), SUM(`Total Amount`) Yearly_Revenue
FROM
    retail_sales_dataset
GROUP BY DATE_FORMAT(Date, '%Y')
ORDER BY Yearly_Revenue DESC
LIMIT 1;


-- Months has highest number of transection

SELECT 
    DATE_FORMAT(Date, '%Y-%b'), COUNT(`Transaction ID`)
FROM
    retail_sales_dataset
GROUP BY DATE_FORMAT(Date, '%Y-%b')
ORDER BY COUNT(`Transaction ID`) DESC
LIMIT 1;


-- Revenue generated during wekend and weekdays
SELECT 
    CASE
        WHEN DAYOFWEEK(Date) IN (1 , 7) THEN 'Week End'
        ELSE 'Weekdays'
    END AS Day_Type,
    SUM(`Total Amount`) Total
FROM
    retail_sales_dataset
GROUP BY Day_Type;




